public class AdivinaNumero {
    public static void main(String[] args) {
        int secreto = 73;
        int[] intentos = {50, 80, 70, 75, 73};
        int idx = 0;
        int intento;
        boolean acierto = false;
        int realizados = 0;

        do {
            intento = intentos[idx++];
            realizados++;
            System.out.print("Attempt " + realizados + ": " + intento);
            if (intento == secreto) {
                acierto = true;
                System.out.println(" - Correct! 🎉");
            } else if (intento < secreto) {
                System.out.println(" - the secret is higher");
            } else {
                System.out.println(" - the secret is lower");
            }
        } while (!acierto && realizados < 5);

        if (!acierto) {
            System.out.println("No matches. The number was " + secreto);
        }
    }
}

