solution:
public class RaizBabilonica {
    public static void main(String[] args) {
        double numero = 144.0;
        double estimacion = numero / 2.0;
        double epsilon = 0.0001;
        int iteraciones = 0;

        while (true) {
            double nueva = (estimacion + numero / estimacion) / 2.0;
            iteraciones++;
            if (Math.abs(nueva - estimacion) < epsilon) {
                estimacion = nueva;
                break;
            }
            estimacion = nueva;
        }

        System.out.printf("Square root of %.1f = %.4f (in %d iterations)%n",
                numero, estimacion, iteraciones);
    }
}
